// Turns the cosmetic art export (scripts/art/cosmetics/export.py -> meta JSON) into the files the
// game reads: art/pixel/cosmetics.gen.ts (ids, levels, palettes) and the generated block of
// theme/recipes.css (one `.r-<id>` rule per recipe, pointing at the baked sprite).
// Called by bake-pixels.mjs; deterministic.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const BEGIN =
  '/* ===== generated: pixel cosmetics (scripts/art/bake-pixels.mjs). Do not edit by hand. ===== */';
const END = '/* ===== end of generated pixel cosmetics ===== */';
const url = (name) => `url('../art/pixel/sprites/cos-${name}.png')`;
const levels = (n) => Array.from({ length: n }, (_, i) => i + 1);

/** The CSS for every recipe the exported art implements. */
export function cosmeticCss(meta) {
  const out = [];
  const rule = (sel, body) => out.push(`${sel} {\n${body.map((l) => `  ${l};`).join('\n')}\n}`);
  // borders: the flourish layer on the frame grid (geometry in the hand-written rules above)
  for (const [id, b] of Object.entries(meta.borders)) {
    for (const lv of levels(b.levels))
      rule(`.r-bd-${id}-${lv} .bi-card__deco::before`, [
        `background-image: ${url(`bd-${id}-${lv}`)}`,
      ]);
    if (b.amb)
      rule(`.r-bd-${id}-${b.levels} .bi-amb--border i`, [`background-image: ${url(b.amb)}`]);
  }
  for (const [id, f] of Object.entries(meta.finishes)) {
    for (const lv of levels(f.levels))
      rule(`.r-fn-${id}-${lv} .bi-card__finish::before`, [
        `background-image: ${url(`fn-${id}-${lv}`)}`,
      ]);
    if (f.pulse)
      rule(`.r-fn-${id}-${f.levels} .bi-card__finish::after`, [
        `background-image: ${url(f.pulse)}`,
        'width: 415.9091%',
        'animation: r-px-pulse 1.5s steps(3, end) infinite',
      ]);
    if (f.amb)
      rule(`.r-fn-${id}-${f.levels} .bi-amb--finish i`, [`background-image: ${url(f.amb)}`]);
  }
  for (const [id, t] of Object.entries(meta.tables))
    for (const lv of levels(t.levels))
      rule(`.r-tb-${id}-${lv} body`, [
        `background-image: radial-gradient(80% 55% at 50% 0%, var(--bi-table-glow, transparent), transparent 70%), ${url(`tb-${id}-${lv}`)}`,
        `background-size: auto, ${t.w * 2}px ${t.h * 2}px`,
        'image-rendering: pixelated',
      ]);
  for (const [id, c] of Object.entries(meta.cursors))
    for (const lv of levels(c.levels))
      rule(`.r-cur-${id}-${lv},\n.r-cur-${id}-${lv} body`, [
        `cursor: ${url(`cur-${id}-${lv}`)} ${c.hot[0]} ${c.hot[1]}, auto`,
      ]);
  for (const [id, t] of Object.entries(meta.ticks))
    for (const lv of levels(t.levels)) rule(`.r-tk-${id}-${lv}`, [`--bi-tick-px: ${id}-${lv}`]);
  for (const [id, n] of Object.entries(meta.numbers))
    for (const lv of levels(n.levels)) rule(`.r-num-${id}-${lv}`, [`--bi-num-px: ${id}-${lv}`]);
  for (const [slot, styles] of Object.entries(meta.skins ?? {}))
    for (const s of styles) rule(`.r-ui-${slot}-${s}`, [`--bi-skin-${slot}: ${s}`]);
  for (const extra of meta.css ?? []) out.push(extra);
  return out.join('\n');
}

/** Writes the generated block into recipes.css (replacing the previous one). */
export function writeCosmeticCss(root, meta) {
  const file = join(root, 'src/renderer/src/theme/recipes.css');
  const css = readFileSync(file, 'utf8');
  const i = css.indexOf(BEGIN);
  const head = (i >= 0 ? css.slice(0, i) : css).trimEnd();
  writeFileSync(file, `${head}\n\n${BEGIN}\n${cosmeticCss(meta)}\n${END}\n`);
  return file;
}

/** Writes art/pixel/cosmetics.gen.ts. */
export function writeCosmeticTs(root, meta) {
  const file = join(root, 'src/renderer/src/art/pixel/cosmetics.gen.ts');
  const rest = { ...meta };
  delete rest.sprites;
  delete rest.css;
  writeFileSync(
    file,
    `// Generated by scripts/art/bake-pixels.mjs from scripts/art/cosmetics/export.py. Do not edit.\n` +
      `/** The cosmetic art of the beta batch (B1-B10): style ids, level counts and palettes. */\n` +
      `export const COSMETIC_META = ${JSON.stringify(rest)} as const;\n`,
  );
  return file;
}
